package com.vandorlabs.neoforge.gear;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Real joined placement, complete bounded capture, native endpoints, inventory edits and process restart. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearJoinedChecks {
    private record Case(BlockPos anchor,Direction mount,NativeGearDefinition kind,boolean rotate) {
        boolean extender(){return kind.kind==NativeGearDefinition.Kind.EXTENDER;}
        boolean carry(){return extender()&&mount.getAxis()==Direction.Axis.Y;}
        BlockPos local(int x,int y,int z){return anchor.offset(NativeGearOrientation.vector(mount,new BlockPos(x,y,z)));}
        List<BlockPos> columns(){return (extender()?List.of(local(0,0,0),local(3,0,0),local(0,0,3),local(3,0,3)):List.of(local(0,0,0),local(2,0,0),local(4,0,0))).stream().sorted().toList();}
        BlockPos root(){return columns().getFirst();}
        List<BlockPos> platform(){var result=new ArrayList<BlockPos>();if(extender()){for(int x=0;x<=3;x++)for(int z=0;z<=3;z++)if(x==0||x==3||z==0||z==3)result.add(local(x,-2,z));}else for(int x=0;x<=4;x++)result.add(local(x,-2,0));return result;}
        BlockPos chest(){return local(1,-2,0).above();}
        int count(){return platform().size()+(carry()?1:0);}
    }
    private static final List<Case> CASES=new ArrayList<>();private static Actor actor;private static ServerLevel world;private static int stage,ticks,checks;private static boolean running;
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211491),"NativeJoinedArms"));}}
    private static String phase(){return System.getProperty("vandorlabs.gearJoinedPhase","");}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native joined stage="+stage+" tick="+ticks+": "+why);}
    private static NativeGearEntity tile(Case scene){var tile=NativeGearFormation.at(world,scene.root());need(tile!=null&&!tile.inert(),"healthy primary "+scene);return tile;}
    private static void position(BlockPos root,Direction mount){var point=NativeGearOrientation.point(mount,-3,1,-3);actor.setPos(root.getX()+point.x,root.getY()+point.y,root.getZ()+point.z);}
    private static void click(Case scene){position(scene.root(),scene.mount);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);need(actor.gameMode.useItemOn(actor,world,ItemStack.EMPTY,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(scene.root()).add(0,0,-.5),Direction.NORTH,scene.root(),false)).consumesAction(),"actual joined manual interaction "+scene);}
    private static void cases(){int index=0;for(var mount:Direction.values())for(var kind:new NativeGearDefinition[]{NativeGearDefinition.EXTENDER,NativeGearDefinition.LARGE_EXTENDER,NativeGearDefinition.ROTATING,NativeGearDefinition.LARGE_ROTATING})for(int mode=0;mode<(kind.kind==NativeGearDefinition.Kind.ROTATING?2:1);mode++){int n=index++;CASES.add(new Case(new BlockPos(20000+n%8*32,110,20000+n/8*32),mount,kind,mode==1));}need(CASES.size()==36,"six faces/sizes/extender/rotatingBothModes");}
    private static void place(Case scene,BlockPos root,int direction){position(root,scene.mount);world.setBlock(root.relative(scene.mount.getOpposite()),Blocks.STONE.defaultBlockState(),3);var choices=NativeGearSettings.defaults().choices();choices.putBoolean("JoinArms",true);choices.putInt("JoinRange",4);choices.putInt("Direction",direction);choices.putBoolean("RotatePayload",scene.rotate);choices.putBoolean("CarryLoad",scene.carry());choices.putInt("LoadHeight",2);var data=new CompoundTag();data.put(NativeGearItem.SETTINGS,choices);var stack=new ItemStack(NativeGearBindings.ITEMS.get(scene.kind.id),2);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);for(int part=0;part<2;part++){var support=root.relative(scene.mount,part-1);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(Vec3.atLowerCornerOf(scene.mount.getNormal()).scale(.5)),scene.mount,support,false)).consumesAction(),"actual joined Survival placement "+scene+" root="+root+" part="+part+" targetState="+world.getBlockState(root.relative(scene.mount,part))+" held="+stack+" player="+actor.position());}need(stack.isEmpty(),"configured section consumption");}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(phase().isEmpty())return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);cases();for(var scene:CASES)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){int cx=(scene.anchor.getX()>>4)+x,cz=(scene.anchor.getZ()>>4)+z;world.setChunkForced(cx,cz,true);world.getChunk(cx,cz);}if(phase().equals("read")){for(var scene:CASES){var root=tile(scene);need(root.progress()==1&&!root.blocked()&&root.payload()!=null&&root.payload().materialized()&&root.columns().size()==scene.columns().size(),"saved joined native rest endpoint "+scene);for(var at:scene.platform())need(world.getBlockState(at).is(Blocks.DIAMOND_BLOCK),"saved native surface "+at);if(scene.carry())need(((ChestBlockEntity)world.getBlockEntity(scene.chest())).getItem(0).getCount()==11,"native edited inventory survives return and restart");}finish("read");return;}for(var scene:CASES){for(int x=-6;x<=9;x++)for(int y=-5;y<=7;y++)for(int z=-6;z<=9;z++)world.setBlock(scene.anchor.offset(x,y,z),y==-5?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),18);for(var root:scene.columns())place(scene,root,0);place(scene,scene.local(-3,0,0),1);}running=true;
    }catch(Throwable failure){failure(failure);}}
    private static void verify(Case scene){var root=tile(scene);need(!root.blocked(),"joined stroke refused "+scene+" "+root.error());if(root.payload()!=null&&!root.payload().materialized())need(root.payload().size()==scene.count()&&root.payloadView()!=null,"complete owned visible platform "+scene);}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<1800,"timeout pending="+CASES.stream().map(scene->scene+"="+tile(scene).progress()+"/"+tile(scene).error()).limit(5).toList());if(stage==0){for(var scene:CASES){var root=tile(scene);if(!root.controller()||root.columns().size()!=scene.columns().size())return;need(root.members().size()==scene.columns().size()*2,"all and only compatible source columns");for(var at:scene.platform())world.setBlock(at,Blocks.DIAMOND_BLOCK.defaultBlockState(),3);if(scene.carry()){world.setBlock(scene.chest(),Blocks.CHEST.defaultBlockState(),3);((ChestBlockEntity)world.getBlockEntity(scene.chest())).setItem(0,new ItemStack(Items.DIAMOND,7));}need(NativeGearJoined.selected(root,java.util.function.Function.identity()).size()==scene.count(),"exact hollow surface and selected load");}var first=CASES.getFirst();world.setBlock(first.platform().getFirst(),Blocks.AIR.defaultBlockState(),3);click(first);stage=1;return;}
        if(stage==1){var first=CASES.getFirst();if(!tile(first).blocked())return;need(tile(first).progress()==1&&tile(first).payload()==null,"disconnected support refuses before ownership removal");for(var at:first.platform())if(!at.equals(first.platform().getFirst()))need(world.getBlockState(at).is(Blocks.DIAMOND_BLOCK),"refused native platform retained");world.setBlock(first.platform().getFirst(),Blocks.DIAMOND_BLOCK.defaultBlockState(),3);click(first);for(var scene:CASES)click(scene);stage=2;return;}
        if(stage==2){boolean complete=true;for(var scene:CASES){verify(scene);var root=tile(scene);if(root.progress()!=0||NativeGearJournal.busy(root)){complete=false;continue;}if(scene.extender()||scene.rotate){if(root.payload()==null||!root.payload().materialized()){if(root.payload()!=null)need(!root.payload().endpoint(root,0).isEmpty(),"rigid joined endpoint must materialize on native grid "+scene+" transform="+root.payload().transform(root,0)+" error="+root.error());complete=false;}}else need(root.payload()!=null&&!root.payload().materialized()&&root.payloadView()!=null,"fractional level platform remains visibly captured");}if(!complete)return;for(var scene:CASES){if(scene.carry()){var chest=(ChestBlockEntity)world.getBlockEntity(scene.chest().relative(scene.mount.getOpposite()));need(chest!=null&&chest.getItem(0).getCount()==7,"native selected chest at active endpoint");chest.setItem(0,new ItemStack(Items.DIAMOND,11));chest.setChanged();}click(scene);}stage=3;return;}
        if(stage==3){for(var scene:CASES){verify(scene);var root=tile(scene);if(root.progress()!=1||root.payload()==null||!root.payload().materialized()||NativeGearJournal.busy(root))return;}for(var scene:CASES){for(var at:scene.platform())need(world.getBlockState(at).is(Blocks.DIAMOND_BLOCK),"native rest surface restored");if(scene.carry())need(((ChestBlockEntity)world.getBlockEntity(scene.chest())).getItem(0).getCount()==11,"native edits retained through recapture");need(!tile(scene).hasStoredSections(),"all displaced joined sections restored");}finish("write");}
    }catch(Throwable failure){failure(failure);}}
    private static void finish(String marker){running=false;System.out.println("[vandorlabs][gear-joined] "+marker+" PASS cases="+CASES.size()+" checks="+checks+" realPlacement/36SixFaceSizeMode/compatibleJoin/hollowCorners/wholeCapture/loadedBounds/nativeEndpoints/chestEdit11/reversal/restart");world.getServer().saveEverything(true,true,true);world.getServer().halt(false);}
    private static void failure(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][gear-joined] "+phase()+" FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
